struct CartItem { let id: Int; let quantity: Int; let stock: Int }
func unavailableIDs(in items: [CartItem]) -> [Int] {
    var result: [Int] = []
    for item in items {
        if item.quantity > item.stock { result.append(item.id) }
    }
    return result
}
let cart = [CartItem(id: 20, quantity: 1, stock: 3),
            CartItem(id: 70, quantity: 4, stock: 2),
            CartItem(id: 10, quantity: 2, stock: 0)]
print(unavailableIDs(in: cart))

Будет [70, 10]. Ранний return убрал бы остальные проблемы, поэтому теперь накапливаем номера и возвращаем массив после всего прохода.

